export class PresentationMinimap{readonly element=document.createElement('div');private readonly canvas=document.createElement('canvas');private readonly ctx:CanvasRenderingContext2D|null;constructor(){this.element.className='dev-minimap';this.element.hidden=true;const t=document.createElement('b');t.textContent='MINIMAP';this.canvas.width=220;this.canvas.height=150;this.ctx=this.canvas.getContext('2d');this.element.append(t,this.canvas)}setVisible(v:boolean){this.element.hidden=!v}get visible(){return !this.element.hidden}update(b:MinimapBounds,pts:readonly MinimapPoint[]){const c=this.ctx;if(!c)return;const w=this.canvas.width,h=this.canvas.height,dx=Math.max(.001,b.maxX-b.minX),dz=Math.max(.001,b.maxZ-b.minZ);c.clearRect(0,0,w,h);c.fillStyle='rgba(8,13,20,.86)';c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.22)';c.strokeRect(.5,.5,w-1,h-1);for(const p of pts){const x=(p.x-b.minX)/dx*w,y=h-(p.z-b.minZ)/dz*h;c.beginPath();c.fillStyle=p.color??'#7cf7d4';c.arc(x,y,p.radius??4,0,Math.PI*2);c.fill();if(p.label){c.fillStyle='#fff';c.font='10px system-ui,sans-serif';c.fillText(p.label,x+6,y-5)}}}}
